local R=dofile('tests/kernel_objects_harness.lua')
local n=0
local function case(name,fn,native)R.menuCase(name,fn,native);n=n+1 end
case('root parent',function(r)r.menu.openObjectsMenu();assert(r.last.menu=='forge_core_server_settings'and #r.last.options==5)end)
case('settings parent route',function(r)r.menu.openServerSettingsMenu();r.select(10);assert(r.last.id=='forge_core_objects')end)
case('fetch denied',function(r)r.rpcHook=function()return false,'invalid_player'end;r.menu.openObjectsMenu()end)
case('fetch malformed',function(r)r.rpcHook=function()return true,false end;r.menu.openObjectsMenu()end)
case('create scene cancel',function(r)r.menu.openObjectsMenu();r.select(1)end)
case('create scene save',function(r)r.inputs={{'New'}};r.menu.openObjectsMenu();r.select(1);r.runTimers()end)
case('create scene failed',function(r)r.inputs={{'New'}};r.menu.openObjectsMenu();r.rpcHook=function()return false,'no_permission'end;r.select(1);r.runTimers()end)
case('debug menu toggles',function(r)r.menu.openObjectsMenu();r.select(2);assert(r.objects.debugIds)end)
case('scene sorted objects',function(r)r.menu.openObjectsScene('1','Fallback');assert(r.last.title=='Scene A'and #r.last.options==5 and r.last.options[3].disabled)end)
case('empty scene removable',function(r)r.menu.openObjectsScene(2,'Empty');assert(not r.last.options[3].disabled)end)
case('rename cancel',function(r)r.menu.openObjectsScene(1,'A');r.select(2)end)
case('rename save',function(r)r.inputs={{'Renamed'}};r.menu.openObjectsScene(1,'A');r.select(2);r.runTimers()end)
case('delete empty confirm',function(r)r.alerts={'confirm'};r.menu.openObjectsScene(2,'B');r.select(3);r.runTimers()end)
case('delete empty cancel',function(r)r.alerts={'cancel'};r.menu.openObjectsScene(2,'B');r.select(3)end)
case('object create cancel',function(r)r.menu.openObjectsScene(1,'A');r.select(1)end)
case('invalid model menu refusal',function(r)r.inputs={{'invalid'}};r.validModel=false;r.menu.openObjectsScene(1,'A');r.select(1)end)
case('object preview confirm',function(r)r.inputs={{'prop_new'}};r.menu.openObjectsScene(1,'A');r.select(1);r.finish(true);r.runTimers()end)
case('object preview cancel',function(r)r.inputs={{'prop_new'}};r.menu.openObjectsScene(1,'A');r.select(1);r.finish(false)end)
case('missing object back to root',function(r)r.menu.openObjectActions(999);assert(r.last.id=='forge_core_objects')end)
case('object actions outline',function(r)r.tick();r.menu.openObjectActions(1);assert(r.last.menu=='forge_core_objects_scene'and #r.last.options==4);r.last.onBack();r.last.onExit()end)
case('scene outline back exit',function(r)r.tick();r.menu.openObjectsScene(1,'A');r.last.onBack();r.last.onExit()end)
case('edit action',function(r)r.menu.openObjectActions(1);r.select(1);r.finish(true)end)
case('duplicate action',function(r)r.menu.openObjectActions(1);r.select(2);r.finish(true);r.runTimers()end)
case('teleport action',function(r)r.menu.openObjectActions(1);r.select(3);assert(r.positions[11].x==1)end)
case('delete object confirm',function(r)r.alerts={'confirm'};r.menu.openObjectActions(1);r.select(4);r.runTimers()end)
case('delete object cancel',function(r)r.alerts={'cancel'};r.menu.openObjectActions(1);r.select(4)end)
case('image URL fallback',function(r)r.library.fivem.blips=nil;r.menu.openObjectsScene(1,'A');assert(r.last.options[5].image=='fixture://images/prop_box.jpg')end)
case('PR command',function(r)assert(r.commands[1].name=='objectspawner');r.commands[1].handler()end)
case('native command restriction false',function(r)assert(r.commands[1].restricted==false);r.commands[1].handler()end,true)
print('PASS objects menu differentials '..n)
